package server

import (
	"html"
	"io"
	"net/http"
	"os"
	"strings"
)

const catalogPageCSS = `
@import url('https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600&family=Fraunces:opsz,wght@9..144,300;9..144,400;9..144,500&display=swap');
@import url('https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css');
:root{color-scheme:dark;--ink:#f4fff6;--muted:#99b6a0;--quiet:#718d78;--line:#31533a;--panel:#0c2816;--panel-2:#12351e;--accent:#7cf29a;--accent-ink:#06210e;--danger:#ff9a82;--display:'Fraunces',ui-serif,Georgia,serif;--sans:'Geist',Inter,ui-sans-serif,system-ui,sans-serif}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:var(--sans);background:#06170d;color:var(--ink)}button,input,select{font:inherit}button{cursor:pointer}.app{min-height:100vh;display:grid;grid-template-columns:268px 1fr;background:radial-gradient(circle at 78% -10%,#194d2b55,transparent 34%),#06170d}.side{position:sticky;top:0;height:100vh;padding:30px 18px;background:#092313e8;border-right:1px solid #23442d;backdrop-filter:blur(18px)}.brand{font:300 30px/1 var(--display);letter-spacing:-.03em;color:#fff;margin:2px 10px 34px}.navbtn,.folderbtn{width:100%;min-height:42px;display:flex;align-items:center;justify-content:space-between;border:1px solid transparent;background:transparent;color:#b8d1be;padding:10px 12px;border-radius:12px;text-align:left;font-weight:500;transition:.16s background,.16s border-color,.16s color}.navbtn:hover,.folderbtn:hover{background:#143a21;color:#fff}.navbtn.active,.folderbtn.active{background:#1a4528;border-color:#2d623b;color:#fff}.count{font-size:11px;color:#81a089;font-variant-numeric:tabular-nums}.folders-head{display:flex;justify-content:space-between;align-items:center;margin:28px 10px 9px;color:#809c87;text-transform:uppercase;letter-spacing:.13em;font-size:11px;font-weight:600}.new-folder{border:0;background:transparent;color:#b7d9be;padding:5px 0;font-size:11px;text-transform:none;letter-spacing:0}.new-folder:hover{color:#fff}.folderrow{display:grid;grid-template-columns:minmax(0,1fr) 58px;align-items:center;gap:3px;border-radius:12px}.folder-actions{min-width:54px;height:30px;border:0;background:transparent;color:#8fb198;border-radius:9px;padding:0 7px;font-size:10px;font-weight:600}.folder-actions:hover,.folder-actions:focus-visible{background:#1f4b2c;color:#fff}.content{padding:42px clamp(24px,4.3vw,72px) 64px;min-width:0}.top{display:flex;align-items:flex-start;justify-content:space-between;gap:22px}.top h1{font:300 clamp(42px,5vw,62px)/.98 var(--display);letter-spacing:-.045em;margin:0 0 10px;color:#fff}.account{display:flex;align-items:center;gap:10px;color:#9bc6a6}.nav-action,.secondary,.primary,.danger{min-height:42px;border-radius:999px;padding:9px 16px;border:1px solid #43684d;font-weight:600;transition:.15s transform,.15s background,.15s border-color,.15s box-shadow;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;white-space:nowrap}.nav-action,.secondary{background:#102e1b;color:#e5f5e8}.nav-action:hover,.secondary:hover{background:#1b4528;border-color:#679175;transform:translateY(-1px)}.primary{background:var(--accent);color:var(--accent-ink);border-color:var(--accent);box-shadow:0 8px 25px #0002}.primary:hover{background:#9af7b0;border-color:#9af7b0;transform:translateY(-1px);box-shadow:0 10px 30px #0004}.danger{background:#4a211c;color:#ffd8d0;border-color:#8d493c}.danger:hover{background:#652b24;border-color:#bd6959}.primary:disabled,.secondary:disabled{cursor:not-allowed;opacity:.45;transform:none}.tools{display:grid;grid-template-columns:minmax(240px,1fr) minmax(175px,auto) auto;gap:11px;margin:34px 0 20px}.tools input,.tools select,dialog input,dialog select{width:100%;min-height:48px;background:#f4fbf5;color:#102516;border:1px solid transparent;border-radius:14px;padding:11px 15px;outline:none;box-shadow:0 1px 0 #ffffff44 inset,0 8px 24px #0002;transition:.15s border-color,.15s box-shadow}.tools input:focus,.tools select:focus,dialog input:focus,dialog select:focus{border-color:#7cf29a;box-shadow:0 0 0 3px #7cf29a33,0 8px 24px #0003}.tools .primary{min-height:48px;padding-inline:20px}.bulk{display:none;align-items:center;gap:10px;padding:11px 14px;border:1px solid #315d3b;border-radius:16px;background:#123620;margin-bottom:18px;box-shadow:0 12px 34px #0003}.bulk.on{display:flex}.bulk select{min-height:40px;background:#f4fbf5;color:#102516;border:0;border-radius:11px;padding:8px 12px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(295px,1fr));gap:20px}.card{position:relative;min-height:358px;background:linear-gradient(150deg,#12371f,#0b2515);border:1px solid #31543a;border-radius:22px;padding:12px 12px 16px;display:flex;flex-direction:column;transition:.2s transform,.2s border-color,.2s box-shadow;outline:none}.card:hover,.card:focus-visible{transform:translateY(-4px);border-color:#6bd889;box-shadow:0 22px 50px #0007}.card.selected{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent),0 20px 50px #0007}.card.dragging{opacity:.55}.preview{position:relative;aspect-ratio:16/9;border-radius:14px;background:#0a2113;margin-bottom:17px;overflow:hidden;border:1px solid #ffffff12}.preview::after{content:'';position:absolute;inset:0;box-shadow:inset 0 0 0 1px #ffffff10;pointer-events:none}.preview img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.card-body{padding:0 5px;display:flex;flex:1;flex-direction:column}.card h3{font:400 22px/1.15 var(--display);letter-spacing:-.02em;margin:0 34px 7px 0;color:#fff}.meta{font-size:12px;line-height:1.5;color:#8eae96}.actions{display:flex;align-items:center;flex-wrap:wrap;gap:4px;margin-top:auto;padding-top:13px}.actions button{min-height:30px;border-radius:10px;padding:5px 6px;gap:5px;font-size:10px;line-height:1;box-shadow:none}.actions button i{font-size:12px;line-height:1}.actions .primary{box-shadow:none}.pick{appearance:none;position:absolute;top:23px;right:23px;width:22px;height:22px;border-radius:7px;border:1px solid #b7cfbd;background:#092113cc;z-index:2;display:grid;place-items:center}.pick:checked{background:var(--accent);border-color:var(--accent)}.pick:checked::after{content:'✓';font-size:14px;font-weight:700;color:#07210f}.empty{display:none;padding:82px 20px;text-align:center;border:1px dashed #31543a;border-radius:22px;color:#83a88c}.empty.on{display:block}.empty h2{font:300 32px var(--display);color:#eaf8ed;margin:0}.toast{position:fixed;right:24px;bottom:24px;background:#eefcf1;color:#102516;padding:14px 18px;border-radius:14px;box-shadow:0 16px 50px #0009;transform:translateY(120px);opacity:0;transition:.2s;z-index:40}.toast.on{transform:none;opacity:1}dialog{width:min(760px,calc(100vw - 30px));max-height:88vh;overflow:auto;background:linear-gradient(145deg,#133a21,#0d2b18);color:#effff2;border:1px solid #4a7254;border-radius:24px;padding:28px;box-shadow:0 35px 90px #000b}dialog::backdrop{background:#020b06c9;backdrop-filter:blur(5px)}dialog h2{font:300 34px/1.08 var(--display);letter-spacing:-.025em;margin:0 0 7px}.dialoghead{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}.dialog-copy{color:#a6c1ac;line-height:1.55;margin:0 0 21px}.dialog-form{display:grid;gap:10px}.dialog-form label,.transferopts>label{font-size:12px;font-weight:600;color:#b5cdbb}.dialog-actions{display:flex;justify-content:flex-end;gap:9px;flex-wrap:wrap;margin-top:20px}.dialog-error{min-height:18px;color:#ffb3a2;font-size:12px}.slidegrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:9px;margin:18px 0}.slidepick{display:flex;gap:9px;align-items:flex-start;padding:13px;background:#183c23;border:1px solid transparent;border-radius:12px}.slidepick:has(input:checked){border-color:#7cf29a;background:#1d492b}.transferopts{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:20px 0}.transferopts fieldset{border:1px solid #41614a;border-radius:14px;padding:12px}.dropover{outline:2px dashed #71ee8b;outline-offset:-4px}.eyebrow{color:#83e99a;text-transform:uppercase;letter-spacing:.13em;font-size:10px;font-weight:600;margin-bottom:8px}.folder-dialog-actions{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-top:20px}.visually-hidden{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:800px){.app{display:block}.side{position:static;height:auto;border:0;padding:19px 16px}.brand{margin-bottom:15px}.side nav,.folderlist{display:flex;gap:7px;overflow:auto}.navbtn,.folderbtn{width:auto;white-space:nowrap}.folderrow{display:flex}.folders-head{margin:18px 8px 7px}.content{padding:28px 16px}.top h1{font-size:42px}.tools{grid-template-columns:1fr 1fr}.tools input{grid-column:1/-1}.grid{grid-template-columns:1fr}.account .signed-in{display:none}.card{min-height:340px}}@media(max-width:520px){.top{align-items:flex-start}.account{flex-wrap:wrap;justify-content:flex-end}.tools{grid-template-columns:1fr}.tools input{grid-column:auto}.bulk{align-items:stretch;flex-direction:column}.transferopts{grid-template-columns:1fr}.folder-dialog-actions{align-items:stretch;flex-direction:column-reverse}.folder-dialog-actions>*{width:100%}}
.side{display:flex;flex-direction:column}.folderlist{min-height:0;overflow:auto}.docslink{margin-top:auto;display:flex;align-items:center;justify-content:space-between;gap:12px;color:#b8d1be;text-decoration:none;padding:15px 12px 2px;border-top:1px solid #23442d;font-size:13px}.docslink:hover{color:#fff}.docslink span:last-child{color:#7cf29a;font-size:15px}@media(max-width:800px){.docslink{margin-top:15px;padding:13px 8px 0}}
.grid{grid-template-columns:repeat(auto-fill,minmax(260px,1fr))}.card{min-height:330px}
`

func documentationURL() string {
	if configured := strings.TrimSpace(os.Getenv("VSTD_DOCS_URL")); configured != "" {
		return configured
	}
	return "https://vessica-studio-docs-production.up.railway.app"
}

func (s *Server) renderCatalogPage(w http.ResponseWriter, userName, role, csrf string, collaboration bool) {
	teamButton := ""
	logout := ""
	if collaboration {
		if role == "owner" {
			teamButton = `<a class="nav-action" href="/team">Team</a>`
		}
		logout = `<button class="secondary" id="logout">Log out</button>`
	}
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	io.WriteString(w, `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Presentations · Vessica Studio</title><style>`+catalogPageCSS+`</style></head><body>
<div class="app"><aside class="side"><div class="brand">Vessica Studio</div><nav id="views" aria-label="Presentation views"></nav><div class="folders-head"><span>Folders</span><button class="new-folder" id="addFolder">New folder</button></div><div class="folderlist" id="folders"></div><a class="docslink" href="`+html.EscapeString(documentationURL())+`" target="_blank" rel="noopener noreferrer"><span>Documentation</span><span>Open</span></a></aside>
<main class="content"><header class="top"><div><h1 id="pageTitle">Presentations</h1><div class="meta signed-in">Signed in as `+html.EscapeString(userName)+`</div></div><div class="account">`+teamButton+logout+`</div></header>
<div class="tools"><label class="visually-hidden" for="search">Search presentations</label><input id="search" type="search" placeholder="Search presentations" aria-label="Search presentations"><label class="visually-hidden" for="sort">Sort presentations</label><select id="sort" aria-label="Sort presentations"><option value="recent">Recently opened</option><option value="alpha">Title A–Z</option><option value="owner">Owner</option></select><button class="primary" id="newDeck">New presentation</button></div>
<div class="bulk" id="bulk"><b id="selectedCount"></b><select id="bulkFolder" aria-label="Move selected presentations"></select><button class="primary" id="moveSelected">Move</button><button class="secondary" id="clearSelected">Clear</button></div><div class="grid" id="cards"></div><div class="empty" id="empty"><h2>Nothing here yet</h2><p>Create a presentation, move one into this folder, or try a different search.</p></div></main></div>
<div class="toast" id="toast" role="status" aria-live="polite"></div>
<dialog id="actionDialog"><div class="eyebrow" id="actionEyebrow"></div><h2 id="actionTitle"></h2><p class="dialog-copy" id="actionCopy"></p><form class="dialog-form" id="actionForm"><label id="actionLabel" for="actionInput"></label><input id="actionInput" autocomplete="off"><div class="dialog-error" id="actionError" role="alert"></div><div class="dialog-actions"><button class="secondary" type="button" id="cancelAction">Cancel</button><button class="primary" id="submitAction">Continue</button></div></form></dialog>
<dialog id="folderDialog"><div class="eyebrow">Folder settings</div><h2>Rename or delete folder</h2><p class="dialog-copy">Folder changes are personal. They never change presentation access or team sharing.</p><form class="dialog-form" id="folderForm"><label for="folderName">Folder name</label><input id="folderName" autocomplete="off"><div class="dialog-error" id="folderError" role="alert"></div><div class="folder-dialog-actions"><button class="danger" type="button" id="deleteFolder">Delete folder</button><div class="dialog-actions"><button class="secondary" type="button" id="cancelFolder">Cancel</button><button class="primary">Save name</button></div></div></form></dialog>
<dialog id="confirmDialog"><div class="eyebrow">Please confirm</div><h2 id="confirmTitle"></h2><p class="dialog-copy" id="confirmCopy"></p><div class="dialog-error" id="confirmError" role="alert"></div><div class="dialog-actions"><button class="secondary" type="button" id="cancelConfirm">Cancel</button><button class="danger" type="button" id="submitConfirm">Confirm</button></div></dialog>
<dialog id="transferDialog"><div class="dialoghead"><div><div class="eyebrow">Slide transfer</div><h2>Send slides to another presentation</h2><div class="meta" id="transferSource"></div></div><button class="secondary" id="closeTransfer">Close</button></div><div class="slidegrid" id="slideChoices"></div><div class="transferopts"><label>Destination<select id="transferTarget"></select></label><fieldset><legend>Transfer type</legend><label><input type="radio" name="transferMode" value="copy" checked> Editable copy</label><br><label><input type="radio" name="transferMode" value="link"> Live linked snapshot</label></fieldset></div><button class="primary" id="submitTransfer">Send selected slides</button></dialog>
<script>
const csrf=`+strconvQuote(csrf)+`,collaboration=`+map[bool]string{true: "true", false: "false"}[collaboration]+`;let data={folders:[],decks:[]},view='all',folder='',selected=new Set(),transferDeck=null,activeFolder=null,actionHandler=null,confirmHandler=null;const $=id=>document.getElementById(id),esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,method='GET',body){const o={method,headers:{}};if(method!=='GET'){o.headers['Content-Type']='application/json';if(csrf)o.headers['X-CSRF-Token']=csrf;o.body=JSON.stringify(body||{})}const r=await fetch(path,o),j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||'HTTP '+r.status);return j}
function say(msg){toast.textContent=msg;toast.classList.add('on');setTimeout(()=>toast.classList.remove('on'),2800)}
function openAction({eyebrow='Presentation',title,copy='',label,value='',submit='Continue',handler}){actionEyebrow.textContent=eyebrow;actionTitle.textContent=title;actionCopy.textContent=copy;actionLabel.textContent=label;actionInput.value=value;submitAction.textContent=submit;actionError.textContent='';actionHandler=handler;actionDialog.showModal();requestAnimationFrame(()=>{actionInput.focus();actionInput.select()})}
function openConfirm({title,copy,submit='Confirm',handler}){confirmTitle.textContent=title;confirmCopy.textContent=copy;submitConfirm.textContent=submit;confirmError.textContent='';confirmHandler=handler;confirmDialog.showModal()}
function counts(){return{all:data.decks.length,mine:data.decks.filter(d=>d.owned).length,shared:data.decks.filter(d=>!d.owned).length,recent:data.decks.filter(d=>d.last_opened_at).length}}
function renderSide(){const c=counts(),items=[['all','All presentations',c.all],['mine','My presentations',c.mine],['shared','Shared with me',c.shared],['recent','Recent',c.recent]];views.innerHTML=items.filter(x=>collaboration||x[0]!=='shared').map(x=>'<button class="navbtn '+(view===x[0]&&!folder?'active':'')+'" data-view="'+x[0]+'"><span>'+x[1]+'</span><span class="count">'+x[2]+'</span></button>').join('');folders.innerHTML=data.folders.map(f=>'<div class="folderrow" data-drop-folder="'+f.id+'"><button class="folderbtn '+(folder===f.id?'active':'')+'" data-folder="'+f.id+'"><span>'+esc(f.name)+'</span><span class="count">'+f.count+'</span></button><button class="folder-actions" data-folder-menu="'+f.id+'" aria-label="Rename or delete '+esc(f.name)+'">Manage</button></div>').join('');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;folder='';render()});document.querySelectorAll('[data-folder]').forEach(b=>b.onclick=()=>{folder=b.dataset.folder;view='all';render()});document.querySelectorAll('[data-folder-menu]').forEach(b=>b.onclick=()=>folderMenu(b.dataset.folderMenu));wireDrops()}
function visibleDecks(){let a=data.decks.filter(d=>!folder||d.folder_id===folder);if(!folder&&view==='mine')a=a.filter(d=>d.owned);if(!folder&&view==='shared')a=a.filter(d=>!d.owned);if(!folder&&view==='recent')a=a.filter(d=>d.last_opened_at);const q=search.value.trim().toLowerCase();if(q)a=a.filter(d=>(d.title+' '+d.storage_key+' '+(d.owner_name||'')).toLowerCase().includes(q));const by=sort.value;a.sort((x,y)=>by==='alpha'?x.title.localeCompare(y.title):by==='owner'?(x.owner_name||'').localeCompare(y.owner_name||''):(Date.parse(y.last_opened_at||0)-Date.parse(x.last_opened_at||0)||x.title.localeCompare(y.title)));return a}
function card(d){const owner=d.owned?(d.visibility==='team'?'Shared with team':'Private'):('Shared by '+(d.owner_name||'teammate')+' · read only');const openLabel=d.owned?'Edit presentation':'View presentation';const openMode=d.owned?'edit':'view';const openIcon=d.owned?'bi-pencil-square':'bi-eye';const visibilityLabel=d.visibility==='team'?'Make presentation private':'Share presentation with team';const visibility=collaboration&&d.owned?'<button class="secondary" data-visibility aria-label="'+visibilityLabel+'" title="'+visibilityLabel+'"><i class="bi '+(d.visibility==='team'?'bi-lock':'bi-people')+'" aria-hidden="true"></i><span>'+(d.visibility==='team'?'Private':'Share')+'</span></button>':'';return '<article class="card '+(selected.has(d.id)?'selected':'')+'" tabindex="0" draggable="true" data-id="'+d.id+'" aria-label="'+esc(openLabel+': '+d.title)+'"><input class="pick" type="checkbox" aria-label="Select '+esc(d.title)+'" '+(selected.has(d.id)?'checked':'')+'><div class="preview" aria-hidden="true"></div><div class="card-body"><h3>'+esc(d.title)+'</h3><div class="meta">'+esc(d.storage_key)+'<br>'+esc(owner)+'</div><div class="actions" aria-label="Presentation actions"><button class="primary" data-launch="'+openMode+'" title="'+openLabel+'"><i class="bi '+openIcon+'" aria-hidden="true"></i><span>'+(d.owned?'Edit':'View')+'</span></button><button class="secondary" data-launch="present" title="Present"><i class="bi bi-play-fill" aria-hidden="true"></i><span>Present</span></button><button class="secondary" data-transfer title="Send slides"><i class="bi bi-files" aria-hidden="true"></i><span>Send</span></button><button class="secondary" data-fork title="Fork presentation"><i class="bi bi-diagram-2" aria-hidden="true"></i><span>Fork</span></button>'+visibility+'</div></div></article>'}
function syncSelectionUI(){document.querySelectorAll('.card').forEach(el=>{const on=selected.has(el.dataset.id);el.classList.toggle('selected',on);const pick=el.querySelector('.pick');if(pick)pick.checked=on});selectedCount.textContent=selected.size+' selected';bulk.classList.toggle('on',selected.size>0)}
function loadThumbnails(){document.querySelectorAll('.card .preview:not([data-thumbnail])').forEach(p=>{p.dataset.thumbnail='1';const card=p.closest('.card'),img=new Image();img.alt='';img.loading='lazy';img.decoding='async';img.src='/api/app/decks/'+encodeURIComponent(card.dataset.id)+'/thumbnail.png';img.onerror=()=>img.remove();p.appendChild(img)})}
function renderCards(){const ds=visibleDecks();cards.innerHTML=ds.map(card).join('');empty.classList.toggle('on',!ds.length);document.querySelectorAll('.card').forEach(el=>{const d=data.decks.find(x=>x.id===el.dataset.id);el.querySelector('.pick').onchange=e=>{e.target.checked?selected.add(d.id):selected.delete(d.id);syncSelectionUI()};el.querySelectorAll('[data-launch]').forEach(b=>b.onclick=e=>{e.stopPropagation();launch(d,b.dataset.launch)});el.querySelector('[data-transfer]').onclick=e=>{e.stopPropagation();openTransfer(d)};el.querySelector('[data-fork]').onclick=e=>{e.stopPropagation();forkDeck(d)};const vb=el.querySelector('[data-visibility]');if(vb)vb.onclick=e=>{e.stopPropagation();visibility(d)};el.ondblclick=e=>{if(e.target.closest('button,input,select,a'))return;launch(d,d.owned?'edit':'view')};el.onkeydown=e=>{if(e.key==='Enter'&&!e.target.closest('button,input,select,a'))launch(d,d.owned?'edit':'view')};el.ondragstart=()=>{el.classList.add('dragging');selected.add(d.id);syncSelectionUI()};el.ondragend=()=>el.classList.remove('dragging')});bulkFolder.innerHTML='<option value="">No folder</option>'+data.folders.map(f=>'<option value="'+f.id+'">'+esc(f.name)+'</option>').join('');syncSelectionUI();loadThumbnails()}
function render(){renderSide();renderCards();pageTitle.textContent=folder?(data.folders.find(f=>f.id===folder)||{}).name||'Folder':({all:'Presentations',mine:'My presentations',shared:'Shared with me',recent:'Recent'}[view])}
async function launch(d,mode){try{const j=await api('/api/app/decks/'+d.id+'/launch','POST',{mode});location.href=j.url}catch(e){say(e.message)}}
async function visibility(d){try{await api('/api/app/decks/'+d.id+'/visibility','PATCH',{visibility:d.visibility==='team'?'private':'team'});say('Sharing updated');load()}catch(e){say(e.message)}}
function forkDeck(d){openAction({title:'Fork presentation',copy:'Create an independent copy you can edit.',label:'Presentation title',value:d.title+' (copy)',submit:'Create fork',handler:async title=>{await api('/api/app/decks/'+d.id+'/fork','POST',{title});say('Presentation forked');load()}})}
async function move(ids,to){if(!ids.length)return;try{await api('/api/app/decks/'+ids[0]+'/folder','PUT',{deck_ids:ids,folder_id:to});selected.clear();say('Presentation'+(ids.length>1?'s':'')+' moved');load()}catch(e){say(e.message)}}
function wireDrops(){document.querySelectorAll('[data-drop-folder]').forEach(row=>{row.ondragover=e=>{e.preventDefault();row.classList.add('dropover')};row.ondragleave=()=>row.classList.remove('dropover');row.ondrop=e=>{e.preventDefault();row.classList.remove('dropover');move([...selected],row.dataset.dropFolder)}})}
function folderMenu(id){activeFolder=data.folders.find(x=>x.id===id);if(!activeFolder)return;folderName.value=activeFolder.name;folderError.textContent='';folderDialog.showModal();requestAnimationFrame(()=>{folderName.focus();folderName.select()})}
async function openTransfer(d,preselected=[]){try{transferDeck=d;const j=await api('/api/app/decks/'+d.id+'/slides');transferSource.textContent=d.title;slideChoices.innerHTML=j.slides.filter(s=>!s.parked).map(s=>'<label class="slidepick"><input type="checkbox" value="'+s.id+'" '+(preselected.includes(s.id)?'checked':'')+'><span><b>'+s.number+'. '+esc(s.title)+'</b><br><span class="meta">'+(s.linked?'Linked snapshot':'Slide')+'</span></span></label>').join('');transferTarget.innerHTML=data.decks.filter(x=>x.owned&&x.id!==d.id).map(x=>'<option value="'+x.id+'">'+esc(x.title)+'</option>').join('');submitTransfer.disabled=!transferTarget.options.length;transferDialog.showModal()}catch(e){say(e.message)}}
async function load(){data=await api('/api/app/catalog');render();const m=location.hash.match(/^#transfer=([A-Za-z0-9_-]+)$/);if(m){history.replaceState(null,'',location.pathname+location.search);const intent=await api('/api/app/slide-transfer-intents/exchange','POST',{token:m[1]}),d=data.decks.find(x=>x.id===intent.source_deck_id);if(!d)throw Error('Source presentation is no longer available');await openTransfer(d,intent.slide_ids)}}
actionForm.onsubmit=async e=>{e.preventDefault();const value=actionInput.value.trim();if(!value){actionError.textContent='Enter a name to continue.';return}submitAction.disabled=true;try{await actionHandler(value);actionDialog.close()}catch(err){actionError.textContent=err.message}finally{submitAction.disabled=false}};cancelAction.onclick=()=>actionDialog.close();
folderForm.onsubmit=async e=>{e.preventDefault();const name=folderName.value.trim();if(!name){folderError.textContent='Folder name cannot be empty.';return}try{await api('/api/app/folders/'+activeFolder.id,'PATCH',{name});folderDialog.close();say('Folder renamed');load()}catch(err){folderError.textContent=err.message}};cancelFolder.onclick=()=>folderDialog.close();deleteFolder.onclick=()=>{const f=activeFolder;folderDialog.close();openConfirm({title:'Delete “'+f.name+'”?',copy:'Presentations inside will return to the root. Sharing and access will not change.',submit:'Delete folder',handler:async()=>{await api('/api/app/folders/'+f.id,'DELETE');if(folder===f.id)folder='';say('Folder deleted');load()}})};
cancelConfirm.onclick=()=>confirmDialog.close();submitConfirm.onclick=async()=>{submitConfirm.disabled=true;try{await confirmHandler();confirmDialog.close()}catch(err){confirmError.textContent=err.message}finally{submitConfirm.disabled=false}};
submitTransfer.onclick=async()=>{const ids=[...slideChoices.querySelectorAll('input:checked')].map(x=>x.value);if(!ids.length){say('Select at least one slide');return}const mode=document.querySelector('input[name=transferMode]:checked').value;try{const j=await api('/api/app/slide-transfers','POST',{source_deck_id:transferDeck.id,target_deck_id:transferTarget.value,slide_ids:ids,mode});transferDialog.close();say(j.slide_ids.length+' slide'+(j.slide_ids.length===1?'':'s')+' sent')}catch(e){say(e.message)}};closeTransfer.onclick=()=>transferDialog.close();
addFolder.onclick=()=>openAction({eyebrow:'Organization',title:'Create a folder',copy:'Folders are personal and never change sharing permissions.',label:'Folder name',submit:'Create folder',handler:async name=>{await api('/api/app/folders','POST',{name});say('Folder created');load()}});newDeck.onclick=()=>openAction({title:'New presentation',copy:'Give the deck a clear working title. You can change it later.',label:'Presentation title',submit:'Create presentation',handler:async title=>{await api('/api/app/decks','POST',{title});say('Presentation created');load()}});
moveSelected.onclick=()=>move([...selected],bulkFolder.value);clearSelected.onclick=()=>{selected.clear();syncSelectionUI()};search.oninput=renderCards;sort.onchange=renderCards;if($('logout'))logout.onclick=async()=>{await api('/api/auth/logout','POST',{});location.replace('/auth/login')};load().catch(e=>say(e.message));
</script></body></html>`)
}
